import { createEarning } from '~/client';
import type { CreateEarningResponse, EarningCreateRequest } from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useCreateEarning = defineMutation(() => {
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (data: EarningCreateRequest): Promise<CreateEarningResponse> =>
      createEarning({
        composable: '$fetch',
        body: ref(data),
      }),
    onSuccess: async (data) => {
      showToastSuccess('Earning created successfully.');
      await navigateTo({
        name: 'earnings-id',
        params: {
          id: data.id,
        },
      });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    createEarning: mutateAsync,
    isCreateEarningLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
