import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import { earningRateTypeValues } from '~/constants/earnings/rateType';

export const earningCreateSchemaObject = {
  canvasser_id: z.string({ message: 'Canvasser is required' }).nonempty('Canvasser is required'),
  project_id: z.string().nullable().default(null),
  description: z
    .string({ message: 'Description is required' })
    .trim()
    .min(1, 'Description is required')
    .max(5000, 'Description must be 5000 characters or fewer'),
  rate_type: z.enum(earningRateTypeValues, { message: 'Rate type is required' }),
  total: z.preprocess(
    (val) => (val === '' || val == null ? NaN : Number(val)),
    z
      .number({ message: 'Total should be a valid number' })
      .positive('Total must be greater than 0')
      .max(1000, 'Total must be 1000 or less')
  ),
};

export const formSchema = toTypedSchema(z.object(earningCreateSchemaObject));
