<template>
  <section class="flex flex-col gap-4">
    <PageTitle title="Create Earning" show-doc>
      <Badge :variant="paymentStatusBadge.ready_for_payment.variant">
        {{ paymentStatusBadge.ready_for_payment.label }}
      </Badge>
    </PageTitle>
    <GoBackButton subject="earnings" :fallback-to="{ name: 'earnings' }" />
    <EarningsCreateForm
      :canvasser-items="canvasserItems"
      :project-items="projectItems"
      :is-loading-canvassers="isLoadingCanvassers"
      :is-loading-projects="isLoadingProjects"
      :canvassers-error="canvassersError"
      :projects-error="projectsError"
      @update:canvasser-id="(id) => (selectedCanvasserId = id)"
    />
  </section>
</template>

<script lang="ts" setup>
import { getSelectorUserList, getSelectorProjectList } from '~/client';
import type { GetSelectorUserListResponse, GetSelectorProjectListResponse } from '~/client';
import { paymentStatusBadge } from '~/constants/earnings/paymentStatus';

definePageMeta({
  roles: ['admin', 'manager'],
  skipNavJourney: true,
});

useSeoMeta({
  title: 'Create Earning',
  description: 'Create a new earning in the system.',
});

const selectedCanvasserId = ref<string | null>(null);

const {
  data: canvassersData,
  isLoading: isLoadingCanvassers,
  error: canvassersError,
} = useQuery({
  key: () => ['selector-canvassers-active'],
  query: (): Promise<GetSelectorUserListResponse> =>
    getSelectorUserList({
      composable: '$fetch',
      query: { roles: ['canvasser'], statuses: ['active'] },
    }),
});

const {
  data: projectsData,
  isLoading: isLoadingProjects,
  error: projectsError,
} = useQuery({
  key: () => ['selector-projects-for-earning-create', selectedCanvasserId.value],
  query: (): Promise<GetSelectorProjectListResponse> =>
    getSelectorProjectList({
      composable: '$fetch',
      query: {
        statuses: ['active'],
        assigned_user_ids: selectedCanvasserId.value ? [selectedCanvasserId.value] : undefined,
      },
    }),
  enabled: () => !!selectedCanvasserId.value,
});

const canvasserItems = computed<SelectItem<string>[]>(() =>
  (canvassersData.value?.users ?? []).map((u) => ({
    name: `${u.first_name} ${u.last_name}`,
    value: u.id,
  }))
);

const projectItems = computed<SelectItem<string>[]>(() =>
  (projectsData.value?.items ?? []).map((p) => ({
    name: p.name,
    value: p.id,
  }))
);
</script>
