<template>
  <form id="createEarningForm" class="flex flex-col gap-4" @submit="onSubmit">
    <Alert variant="info">
      <CircleAlert />
      <AlertTitle> This earning will be created with <strong>Ready for Payment</strong> </AlertTitle>
      <AlertDescription> It will be available for the next payroll cycle or for same-day payout </AlertDescription>
    </Alert>

    <Card>
      <CardHeader>
        <CardTitle>Recipient & Project</CardTitle>
        <CardDescription>
          Pick the canvasser first — their assigned projects will appear in the next field.
        </CardDescription>
      </CardHeader>
      <CardContent>
        <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
          <FormItemWrapper label="Canvasser" name="canvasser_id" is-required>
            <template #default="{ slots }">
              <KitFormsCombobox
                id="canvasser_id"
                :items="canvasserItems"
                :null-is-all="false"
                placeholder="Select a canvasser"
                input-placeholder="Search canvasser..."
                empty-text="No canvassers found"
                :component-field="slots.componentField"
                :disabled="isLoadingCanvassers"
                :loading="isLoadingCanvassers"
                loading-text="Loading canvassers..."
                :error="canvassersError ? canvassersError?.data?.detail || 'Failed to load canvassers' : ''"
                @change="onCanvasserChange"
              />
            </template>
          </FormItemWrapper>

          <FormItemWrapper label="Project" name="project_id">
            <template #default="{ slots }">
              <div class="flex flex-col gap-1">
                <KitFormsCombobox
                  id="project_id"
                  :items="projectItems"
                  :null-is-all="true"
                  :placeholder="projectPlaceholder"
                  input-placeholder="Search project..."
                  empty-text="No projects found"
                  :component-field="slots.componentField"
                  :disabled="isProjectComboboxDisabled"
                  :loading="isLoadingProjects"
                  loading-text="Loading projects..."
                  :error="projectsError ? projectsError?.data?.detail || 'Failed to load projects' : ''"
                />
                <p v-if="selectedCanvasserId" class="text-xs text-muted-foreground">
                  Optional — leave blank for non-project earnings.
                </p>
              </div>
            </template>
          </FormItemWrapper>
        </div>
      </CardContent>
    </Card>

    <Card
      :class="['transition-opacity', !selectedCanvasserId && 'opacity-60 pointer-events-none']"
      :aria-disabled="!selectedCanvasserId || undefined"
      :inert="!selectedCanvasserId || undefined"
    >
      <CardHeader>
        <CardTitle>Earning Details</CardTitle>
        <CardDescription>Type, amount, and what this earning is for.</CardDescription>
      </CardHeader>
      <CardContent>
        <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
          <FormItemWrapper label="Rate Type" name="rate_type" is-required>
            <template #default="{ slots }">
              <KitFormsSelect id="rate_type" :items="earningRateTypes" :component-field="slots.componentField" />
            </template>
          </FormItemWrapper>

          <FormItemWrapper label="Total" name="total" is-required>
            <template #default="{ slots }">
              <div class="relative text-black w-full">
                <MoneyInput id="total" class="pl-6" v-bind="slots.componentField" />
                <span class="absolute start-0 inset-y-0 flex items-center justify-center px-1">
                  <DollarSign class="size-5" />
                </span>
              </div>
            </template>
          </FormItemWrapper>

          <FormItemWrapper label="Description" name="description" is-required item-class="col-span-1 md:col-span-2">
            <template #default="{ slots }">
              <Textarea
                id="description"
                class="resize-none"
                placeholder="Describe what this earning is for"
                v-bind="slots.componentField"
                rows="7"
              />
            </template>
          </FormItemWrapper>
        </div>
      </CardContent>
    </Card>

    <div class="flex justify-end items-center">
      <Button type="submit" :loading="isCreateEarningLoading">Create Earning</Button>
    </div>
  </form>
</template>

<script lang="ts" setup>
import { useForm } from 'vee-validate';
import { CircleAlert, DollarSign } from 'lucide-vue-next';
import { formSchema } from '~/constants/validationSchemas/earningCreate';
import { earningRateTypes } from '~/constants/earnings/rateType';
import { useCreateEarning } from '~/mutations/earnings/create';

interface Props {
  canvasserItems: SelectItem<string>[];
  projectItems: SelectItem<string>[];
  isLoadingCanvassers: boolean;
  isLoadingProjects: boolean;
  canvassersError: any;
  projectsError: any;
}

const props = defineProps<Props>();

const emit = defineEmits<{ 'update:canvasserId': [value: string | null] }>();

const { createEarning, isCreateEarningLoading } = useCreateEarning();

const { handleSubmit, values, setFieldValue } = useForm({
  validationSchema: formSchema,
});

const selectedCanvasserId = computed<string | null>(() => values.canvasser_id ?? null);

const isProjectComboboxDisabled = computed<boolean>(() => !selectedCanvasserId.value || props.isLoadingProjects);

const projectPlaceholder = computed<string>(() =>
  selectedCanvasserId.value ? 'No project' : 'Select a canvasser first'
);

function onCanvasserChange(value: string | number | Record<string, string[]> | null) {
  emit('update:canvasserId', typeof value === 'string' ? value : null);
  setFieldValue('project_id', null);
}

const onSubmit = handleSubmit((formValues) =>
  createEarning({
    canvasser_id: formValues.canvasser_id,
    project_id: formValues.project_id,
    description: formValues.description,
    rate_type: formValues.rate_type,
    total: formValues.total,
  })
);
</script>
